/1498|qq=}}) || |- | align="center" | 73 || {{ill|Munakata Okoshi|ja|宗像貞氏|lt=Okoshi|lt_ja=興氏|qq=draft|12=simple|13=User:Immanuelle/Munakata Okoshi|qq=}} || Meiō 8 ({{ill|1499|ja|1499th year|qq=draft|12=simple|13=User:Immanuelle/1499|qq=}}) || |- | align="center" | 74 || {{ill|Munakata Ujisa|ja|宗像氏佐|lt=Ujisa|lt_ja=氏佐|qq=draft|12=simple|13=User:Immanuelle/Munakata Ujisa|qq=}} || Meiō 9 ({{ill|1500|ja|1500th year|qq=draft|12=simple|13=User:Immanuelle/1500|qq=}}) – {{ill|Bunkimei|ja|文亀|qq=draft|12=simple|13=User:Immanuelle/Bunkimei|qq=}} 3 ({{ill|1503|ja|1503rd year|qq=draft|12=simple|13=User:Immanuelle/1503|qq=}}) || |- | align="center" | 75 || {{ill|Munakata Okoshi|ja|宗像貞氏|lt=Okoshi|lt_ja=興氏|qq=draft|12=simple|13=User:Immanuelle/Munakata Okoshi|qq=}} || {{ill|Eishō|ja|永正|qq=draft|12=simple|13=User:Immanuelle/Eishō|qq=}} 1 ({{ill|1504|ja|1504th year|qq=draft|12=simple|13=User:Immanuelle/1504|qq=}}) || |- | align="center" | 76(-) || {{ill|Munakata Tadashi? (Masashi)|ja|宗像正氏|lt=Tadashi? (Masashi)|lt_ja=正氏|qq=draft|12=simple|13=User:Immanuelle/Munakata Tadashi? (Masashi)|qq=}} || || | &nbsp; |- | align="center" | 77(76) || {{ill|Munakata Ujitsugu|ja|宗像氏続|lt=Ujitsugu|lt_ja=氏続|qq=draft|12=simple|13=User:Immanuelle/Munakata Ujitsugu|qq=}} || {{ill|Eishō|ja|永正|qq=draft|12=simple|13=User:Immanuelle/Eishō|qq=}} 2 ({{ill|1505|ja|1505th year|qq=draft|12=simple|13=User:Immanuelle/1505|qq=}}) || |- | align="center" | 78(77) || {{ill|Munakata Tadashi? (Masashi)|ja|宗像正氏|lt=Tadashi? (Masashi)|lt_ja=正氏|qq=draft|12=simple|13=User:Immanuelle/Munakata Tadashi? (Masashi)|qq=}} || {{ill|Eishō|ja|永正|qq=draft|12=simple|13=User:Immanuelle/Eishō|qq=}} 3 ({{ill|1506|ja|1506th year|qq=draft|12=simple|13=User:Immanuelle/1506|qq=}}) – {{ill|Tenmon|ja|天文|qq=draft|12=simple|13=User:Immanuelle/Tenmon|qq=}} 15 ({{ill|1546|ja|1546th year|qq=draft|12=simple|13=User:Immanuelle/1546|qq=}}) || [[Yamada Incident]] |- | align="center" | 79(78) || {{ill|Munakata Ujiotoko|ja|宗像氏男|lt=Ujiotoko|lt_ja=氏男|qq=draft|1